	"text": ...,
	"document_name": ...,
	"court_name": ...,
	"judge_full_name": ...,
	"document_number": ...,
	"document_date": ...,
	"debtor_full_name": ...,
	"debtor_birth_date": ...,
	"debtor_birth_address": ...,
	"debtor_passport_number": ...,
	"debtor_passport_date": ...,
	"debtor_registration_address": ...,
	"credit_number": ...,
	"credit_date": ...,
	"fee": ...,
	"overdue_debt": ...,
	"main_debt": ...,
	"percent_debt": ...,
	"penalty_debt": ...,
	"other_debt": ...,
	"total_debt": ...,
	"document_series_number": ...
}
```

